Here is the commit message:
drm/vc4: Fix a memory leak in hang state error path
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

When vc4_save_hang_state() encounters an early return condition, it
returns without freeing the previously allocated `kernel_state`,
leaking memory.

Add the missing kfree() calls by consolidating the early return paths
into a single place.

Fixes: 214613656b51 ("drm/vc4: Add an interface for capturing the GPU state after a hang.")
Reviewed-by: Melissa Wen <mwen@igalia.com>
Link: https://patch.msgid.link/20260330-vc4-misc-fixes-v1-3-92defc940a29@igalia.com
Signed-off-by: Maíra Canal <mcanal@igalia.com>

Here is the root cause:
The function `vc4_save_hang_state()` allocates memory for `kernel_state` at the beginning. In two early return paths (when no jobs are found or when allocation of `kernel_state->bo` fails), the function returns without freeing `kernel_state`, causing a memory leak. The patch consolidates these early returns into a common error path that frees the allocated memory before returning.

Here is the patch:

 static void
 vc4_save_hang_state(struct drm_device *dev)
 {
 	struct vc4_dev *vc4 = to_vc4_dev(dev);
 	struct drm_vc4_get_hang_state *state;
 	struct vc4_hang_state *kernel_state;
 	struct vc4_exec_info *exec[2];
 	struct vc4_bo *bo;
 	unsigned long irqflags;
 	unsigned int i, j, k, unref_list_count;

 	kernel_state = kzalloc_objs(*kernel_state, 1);
 	if (!kernel_state)
 		return;

 	state = &kernel_state->user_state;

 	spin_lock_irqsave(&vc4->job_lock, irqflags);
 	exec[0] = vc4_first_bin_job(vc4);
 	exec[1] = vc4_first_render_job(vc4);
-	if (!exec[0] && !exec[1]) {
-		spin_unlock_irqrestore(&vc4->job_lock, irqflags);
-		return;
-	}
+	if (!exec[0] && !exec[1])
+		goto err_free_state;

 	/* Get the bos from both binner and renderer into hang state. */
 	state->bo_count = 0;
 	for (i = 0; i < 2; i++) {
 		if (!exec[i])
 			continue;

 		unref_list_count = 0;
 		list_for_each_entry(bo, &exec[i]->unref_list, unref_head)
 			unref_list_count++;
 		state->bo_count += exec[i]->bo_count + unref_list_count;
 	}

 	kernel_state->bo = kzalloc_objs(*kernel_state->bo, state->bo_count,
 					GFP_ATOMIC);

-	if (!kernel_state->bo) {
-		spin_unlock_irqrestore(&vc4->job_lock, irqflags);
-		return;
-	}
+	if (!kernel_state->bo)
+		goto err_free_state;

 	k = 0;
 	for (i = 0; i < 2; i++) {
 		if (!exec[i])
 			continue;

 		for (j = 0; j < exec[i]->bo_count; j++) {
 			bo = to_vc4_bo(exec[i]->bo[j]);

 			/* Retain BOs just in case they were marked purgeable.
 			 * This prevents the BO from being purged before
 			 * someone had a chance to dump the hang state.
 			 */
 			WARN_ON(!refcount_read(&bo->usecnt));
 			refcount_inc(&bo->usecnt);
 			drm_gem_object_get(exec[i]->bo[j]);
 			kernel_state->bo[k++] = exec[i]->bo[j];
 		}

 		list_for_each_entry(bo, &exec[i]->unref_list, unref_head) {
 			/* No need to retain BOs coming from the ->unref_list
 			 * because they are naturally unpurgeable.
 			 */
 			drm_gem_object_get(&bo->base.base);
 			kernel_state->bo[k++] = &bo->base.base;
 		}
 	}

 	WARN_ON_ONCE(k != state->bo_count);

 	if (exec[0])
 		state->start_bin = exec[0]->ct0ca;
 	if (exec[1])
 		state->start_render = exec[1]->ct1ca;

 	spin_unlock_irqrestore(&vc4->job_lock, irqflags);

 	state->ct0ca = V3D_READ(V3D_CTNCA(0));
 	state->ct0ea = V3D_READ(V3D_CTNEA(0));

 	state->ct1ca = V3D_READ(V3D_CTNCA(1));
 	state->ct1ea = V3D_READ(V3D_CTNEA(1));

 	state->ct0cs = V3D_READ(V3D_CTNCS(0));
 	state->ct1cs = V3D_READ(V3D_CTNCS(1));

 	state->ct0ra0 = V3D_READ(V3D_CT00RA0);
 	state->ct1ra0 = V3D_READ(V3D_CT01RA0);

 	state->bpca = V3D_READ(V3D_BPCA);
 	state->bpcs = V3D_READ(V3D_BPCS);
 	state->bpoa = V3D_READ(V3D_BPOA);
 	state->bpos = V3D_READ(V3D_BPOS);

 	state->vpmbase = V3D_READ(V3D_VPMBASE);

 	state->dbge = V3D_READ(V3D_DBGE);
 	state->fdbgo = V3D_READ(V3D_FDBGO);
 	state->fdbgb = V3D_READ(V3D_FDBGB);
 	state->fdbgr = V3D_READ(V3D_FDBGR);
 	state->fdbgs = V3D_READ(V3D_FDBGS);
 	state->errstat = V3D_READ(V3D_ERRSTAT);

 	/* We need to turn purgeable BOs into unpurgeable ones so that
 	 * userspace has a chance to dump the hang state before the kernel
 	 * decides to purge those BOs.
 	 * Note that BO consistency at dump time cannot be guaranteed. For
 	 * example, if the owner of these BOs decides to re-use them or mark
 	 * them purgeable again there's nothing we can do to prevent it.
 	 */
 	for (i = 0; i < kernel_state->user_state.bo_count; i++) {
 		struct vc4_bo *bo = to_vc4_bo(kernel_state->bo[i]);

 		if (bo->madv == __VC4_MADV_NOTSUPP)
 			continue;

 		mutex_lock(&bo->madv_lock);
 		if (!WARN_ON(bo->madv == __VC4_MADV_PURGED))
 			bo->madv = VC4_MADV_WILLNEED;
 		refcount_dec(&bo->usecnt);
 		mutex_unlock(&bo->madv_lock);
 	}

 	spin_lock_irqsave(&vc4->job_lock, irqflags);
 	if (vc4->hang_state) {
 		spin_unlock_irqrestore(&vc4->job_lock, irqflags);
 		vc4_free_hang_state(dev, kernel_state);
 	} else {
 		vc4->hang_state = kernel_state;
 		spin_unlock_irqrestore(&vc4->job_lock, irqflags);
 	}
+
+	return;
+
+err_free_state:
+	spin_unlock_irqrestore(&vc4->job_lock, irqflags);
+	kfree(kernel_state);
 }



